function monthlyPayment(P, annualPct, years){
  var r = annualPct/100/12, n = years*12;
  if(r === 0) return P/n;
  var f = Math.pow(1+r, n);
  return P*r*f/(f-1);
}
function totalPaid(P, annualPct, years){ return monthlyPayment(P, annualPct, years) * years * 12; }
function totalInterest(P, annualPct, years){ return totalPaid(P, annualPct, years) - P; }
function schedule(P, annualPct, years){
  var r = annualPct/100/12, n = years*12, M = monthlyPayment(P, annualPct, years);
  var bal = P, rows = [];
  for(var i=1; i<=n; i++){
    var interest = bal*r, principal = M - interest;
    bal -= principal;
    rows.push({month:i, payment:M, principal:principal, interest:interest, balance:Math.max(0,bal)});
  }
  return rows;
}
var EXPORTS = { monthlyPayment:monthlyPayment, totalPaid:totalPaid, totalInterest:totalInterest, schedule:schedule };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MortgageForgePure = EXPORTS; }
